async def _gate_sdk_seam(client, *, prompt, system):
    from nora.agent.structured import ask_structured
    got = await ask_structured(
        model=client._model, prompt=prompt, schema=dict,
        timeout_seconds=client._timeout_seconds, system_prompt=system,
    )
    return GateCompletion(content=got.content, finish_reason=got.finish_reason)

@property
def model(self) -> str:
    return self._model

async def complete(self, *, system: str, prompt: str) -> GateCompletion:
    return await self._sdk_verdict(system=system, prompt=prompt)
